+      const tail = 0.6 * Math.sin(((along - aEnd) / 18) * Math.PI * 2);
+      const kk = THREE.MathUtils.smoothstep(along, aEnd - 4, aEnd + 6);
+      ctr[k] = lane + painted * (1 - kk) + tail * kk;
+    }
