+    for (let pass = 0; pass < 4; pass++) {
+      const c0 = ctr.slice();
+      for (let k = 1; k < 63; k++) ctr[k] = 0.25 * c0[k - 1] + 0.5 * c0[k] + 0.25 * c0[k + 1];
