+    shared.uCtrA.value.z = 1;
+    console.info('[m07nearw] checkpoint s', sCk.toFixed(2), 'centre line', ctr.map((v) => v.toFixed(2)).join(' '));
+  }
   const mat = (tile: THREE.Texture, mode: number, k = 1) => new THREE.ShaderMaterial({
